# Numerical search implementation
n_range = range(1, 13)
p_range = range(1, 11)
q_range = range(1, 11)

max_S_by_n = {}

print("--- Starting Numerical Search ---")

for n in n_range:
    max_S_for_n = -float('inf')
    found_valid_S = False

    for p in p_range:
        for q in q_range:
            # Calculate S
            try:
                S = (12 + n) / p + (13 - n) / q
            except ZeroDivisionError:
                # Should not happen since p and q start from 1
                continue

            if S < 1:
                found_valid_S = True
                if S > max_S_for_n:
                    max_S_for_n = S

    if found_valid_S:
        max_S_by_n[n] = max_S_for_n
    else:
        max_S_by_n[n] = "No S < 1 found for this n in the given range"

print("\n--- Results: Maximum S found for each n (where S < 1) ---")
# Print results formatted for easy reading
for n, max_S in sorted(max_S_by_n.items()):
    if isinstance(max_S, float):
        print(f"n = {n}: max S = {max_S}")
    else:
        print(f"n = {n}: {max_S}")

# Also find the overall maximum S found
all_S_values = [max_S for max_S in max_S_by_n.values() if isinstance(max_S, float)]

if all_S_values:
    overall_max_S = max(all_S_values)
    print(f"\nOverall maximum S found across all n: {overall_max_S}")
else:
    print("\nNo values of S < 1 were found across the entire search space.")

